package run.ikaros.document; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/documents") public class DocumentController{private final DocumentService service;public DocumentController(DocumentService s){service=s;}@PostMapping public Mono<DocumentView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateDocumentRequest r){return service.create(o,r);}@GetMapping public Flux<DocumentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.list(o);}@GetMapping("/{id}/working-copy")public Mono<WorkingCopyView> copy(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id){return service.workingCopy(o,id);}@PutMapping("/{id}/working-copy")public Mono<WorkingCopyView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id,@Valid@RequestBody UpdateWorkingCopyRequest r){return service.updateWorkingCopy(o,id,r);}@PostMapping("/{id}/revisions")public Mono<RevisionView> commit(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id,@Valid@RequestBody CommitRevisionRequest r){return service.commit(o,id,r);}@GetMapping("/{id}/revisions")public Flux<RevisionView> revisions(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id){return service.revisions(o,id);}@PostMapping("/{id}/revisions/{n}/actions/restore")public Mono<RevisionView> restore(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id,@PathVariable long n){return service.restore(o,id,n);}@PostMapping("/{id}/actions/publish")public Mono<DocumentPublicationEntity> publish(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id,@Valid@RequestBody PublishDocumentRequest r){return service.publish(o,id,r);}@PostMapping("/{id}/actions/unpublish")public Mono<DocumentPublicationEntity> unpublish(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID id){return service.unpublish(o,id);}}
